    {
        if (is_numeric($invoiceNumber)) {
            $invoiceNumber = (int) $invoiceNumber;
        } elseif (is_string($invoiceNumber)) {
            $matches = [];
            if (preg_match('/^(?:' . Configuration::get('PS_INVOICE_PREFIX', Context::getContext()->language->id) . ')\s*([0-9]+)$/i', $invoiceNumber, $matches)) {
